// §14.1 Visitas: el codigo para el visitante y el aviso de que ya entro.
//
// Aqui solo se redacta. La ventana de validez, los usos y el consumo del uso
// ya los decidio Spring (§10); n8n no recalcula nada de eso.

const esperado = $env.PORTERIA_SECRET;
const publica = $env.PORTERIA_URL_PUBLICA || 'http://localhost:8080';
const admin = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const evento = item.json.body || item.json;

  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  const d = evento.datos || {};
  const apto = d.apartamento || 'sin apartamento';
  const destinatario = d.correoResidente || admin;
  let asunto;
  let texto;

  if (evento.tipo === 'AUTORIZACION_CREADA') {
    asunto = 'Codigo de ingreso para ' + d.visitanteNombre;
    texto = [
      'Autorizaste el ingreso de ' + d.visitanteNombre + ' al apartamento ' + apto + '.',
      '',
      'CODIGO: ' + d.codigo,
      '',
      'Valido desde ' + d.validaDesde + ' hasta ' + d.validaHasta + '.',
      'Comparte este codigo con tu visitante. En la porteria lo pediran junto',
      'con su nombre y los ultimos cuatro digitos del documento.',
      '',
      // El QR NO va incrustado en el correo, y es a proposito: generarlo aqui
      // obligaria a mandar el codigo a un servicio externo de imagenes, y ese
      // codigo abre la puerta del conjunto (§16). El QR se genera en el
      // navegador del residente, que es donde el codigo ya esta.
      'Ver el codigo QR: ' + publica + '/residente.html',
    ].join('\n');

  } else if (evento.tipo === 'INGRESO_REGISTRADO') {
    asunto = d.visitanteNombre + ' acaba de ingresar';
    texto = [
      d.visitanteNombre + ' ingreso al apartamento ' + apto + '.',
      'Registrado por ' + d.vigilante + ' a las ' + d.ingresoEn + '.',
      d.origen === 'NO_ANUNCIADA'
        ? 'Entro con tu aprobacion de la visita no anunciada.'
        : '',
      '',
      'Si no esperabas esta visita, avisa a la porteria.',
    ].filter(Boolean).join('\n');

  } else {
    console.log('Tipo que no corresponde a este flujo: ' + evento.tipo);
    continue;
  }

  salida.push({ json: { tipo: evento.tipo, destinatario, asunto, texto } });
}

return salida;
